import {describe, expect, it} from 'vitest';
import type {DcbEvent} from './events';
import {projectGraph} from './graphProjector/graphProjector';
import {projectWorkspace} from './workspaceProjector';

// A fixed v1 editor history (not generated by the current event factories): the
// literal payloads and tags must continue to replay unchanged after extraction.
const history = [
  {type: 'ProjectAdded', payload: {projectId: 'p1', name: 'Original'}, tags: ['projectId:p1']},
  {type: 'ChapterAdded', payload: {projectId: 'p1', chapterId: 'c1', title: 'First'}, tags: ['projectId:p1', 'chapterId:c1']},
  {type: 'ChapterAdded', payload: {projectId: 'p1', chapterId: 'c2', title: 'Second'}, tags: ['projectId:p1', 'chapterId:c2']},
  {type: 'ProjectRenamed', payload: {projectId: 'p1', newName: 'Renamed'}, tags: ['projectId:p1']},
  {type: 'ChapterRenamed', payload: {projectId: 'p1', chapterId: 'c1', newTitle: 'Updated'}, tags: ['projectId:p1', 'chapterId:c1']},
  {type: 'ProjectAdded', payload: {projectId: 'p2', name: 'Another'}, tags: ['projectId:p2']},
  {
    type: 'NodeAdded',
    payload: {projectId: 'p1', chapterId: 'c1', nodeId: 'n1', type: 'evt', laneId: 1, label: 'Started'},
    tags: ['projectId:p1', 'chapterId:c1', 'nodeId:n1', 'type:evt'],
  },
  {
    type: 'NodeAdded',
    payload: {projectId: 'p1', chapterId: 'c1', nodeId: 'n2', type: 'rm', laneId: 2, label: 'View'},
    tags: ['projectId:p1', 'chapterId:c1', 'nodeId:n2', 'type:rm'],
  },
  {
    type: 'NodesConnected',
    payload: {projectId: 'p1', sourceNodeId: 'n1', targetNodeId: 'n2', role: 'flow'},
    tags: ['projectId:p1', 'nodeId:n1', 'nodeId:n2', 'role:flow', 'connection:n1->n2'],
  },
  {type: 'NodeRenamed', payload: {projectId: 'p1', nodeId: 'n1', newName: 'Completed'}, tags: ['projectId:p1', 'nodeId:n1']},
  {type: 'NodeTypeChanged', payload: {projectId: 'p1', nodeId: 'n1', newType: 'cmd'}, tags: ['projectId:p1', 'nodeId:n1', 'type:cmd']},
  {
    type: 'NodeSchemaChanged',
    payload: {projectId: 'p1', nodeId: 'n1', schema: [{propertyId: 'prop', name: 'Name', type: 'string'}]},
    tags: ['projectId:p1', 'nodeId:n1'],
  },
  {
    type: 'NodeExampleValuesChanged',
    payload: {projectId: 'p1', nodeId: 'n1', exampleValues: [{propertyId: 'prop', scalarValue: 'example'}]},
    tags: ['projectId:p1', 'nodeId:n1'],
  },
  {
    type: 'NodeChapterChanged',
    payload: {projectId: 'p1', nodeId: 'n2', chapterId: 'c2'},
    tags: ['projectId:p1', 'nodeId:n2', 'chapterId:c2'],
  },
  {
    type: 'NodeAdded',
    payload: {projectId: 'p2', chapterId: 'other', nodeId: 'foreign', type: 'ui', laneId: 0, label: 'Other project'},
    tags: ['projectId:p2', 'chapterId:other', 'nodeId:foreign', 'type:ui'],
  },
] satisfies DcbEvent[];
const replayedHistory = JSON.parse(JSON.stringify(history)) as DcbEvent[];

describe('existing serialized editor history', () => {
  it('replays workspace names, order and scope without changing the saved event stream', () => {
    const saved = JSON.stringify(history);
    expect(projectWorkspace(replayedHistory)).toEqual({
      projects: [
        {id: 'p1', name: 'Renamed'},
        {id: 'p2', name: 'Another'},
      ],
      chaptersByProjectId: {
        p1: [
          {id: 'c1', title: 'Updated'},
          {id: 'c2', title: 'Second'},
        ],
        p2: [],
      },
      latestProjectId: 'p2',
    });
    expect(JSON.stringify(history)).toBe(saved);
  });

  it('replays graph edits, properties and chapter moves across project scopes', () => {
    expect(projectGraph(replayedHistory, 'p1', 'c1')).toEqual({
      nodes: [{nodeId: 'n1', nodeType: 'cmd', laneId: 1, label: 'Completed'}],
      edges: [],
      lanes: [{id: 'lane-1', order: 1}],
      nodeSchemas: {n1: [{propertyId: 'prop', name: 'Name', type: 'string'}]},
      nodeExampleValues: {n1: [{propertyId: 'prop', scalarValue: 'example'}]},
    });
    expect(projectGraph(replayedHistory, 'p1', 'c2')).toEqual({
      nodes: [{nodeId: 'n2', nodeType: 'rm', laneId: 2, label: 'View'}],
      edges: [],
      lanes: [{id: 'lane-2', order: 2}],
      nodeSchemas: {},
      nodeExampleValues: {},
    });
    expect(projectGraph(replayedHistory, 'p1').edges).toEqual([{sourceNodeId: 'n1', targetNodeId: 'n2', role: 'flow'}]);
    expect(projectGraph(replayedHistory, 'p2').nodes).toEqual([{nodeId: 'foreign', nodeType: 'ui', laneId: 0, label: 'Other project'}]);
  });
});
